<x-admin-layout title="Payment Details"><section class="form-page-heading"><a href="{{ route('admin.payments.index') }}">← Back to payments</a><h2>{{ $payment->gateway === 'free' ? 'Free subscription details' : 'Payment details' }}</h2><p>{{ $payment->gateway === 'free' ? 'FREE-'.str_pad($payment->id,6,'0',STR_PAD_LEFT) : ($payment->gateway_payment_id ?: $payment->gateway_order_id) }}</p></section><section class="panel payment-detail"><div class="claim-meta-grid"><div><span>CUSTOMER</span><b>{{ $payment->user->name }}</b><small>{{ $payment->user->email }} · {{ $payment->user->phone ?: 'No phone' }}</small></div><div><span>PLAN</span><b>{{ $payment->plan->name }}</b><small>{{ $payment->plan->duration_label }}</small></div><div><span>AMOUNT</span><b>{{ $payment->formatted_amount }}</b><small>{{ $payment->currency }}</small></div><div><span>STATUS</span><b>{{ ucfirst(str_replace('_',' ',$payment->status)) }}</b><small>{{ $payment->paid_at?->format('d M Y, h:i A') ?: 'Not completed' }}</small></div><div><span>TYPE</span><b>{{ $payment->gateway === 'free' ? 'Free plan activation' : ucfirst($payment->gateway) }}</b></div><div><span>ORDER ID</span><b>{{ $payment->gateway === 'free' ? 'Not applicable' : $payment->gateway_order_id }}</b></div><div><span>PAYMENT ID</span><b>{{ $payment->gateway_payment_id ?: '—' }}</b></div><div><span>METHOD</span><b>{{ $payment->gateway === 'free' ? 'No payment required' : ucfirst($payment->metadata['method'] ?? 'Not available') }}</b></div></div></section></x-admin-layout>
